    (270, 'DeepCoolAI (Data Center - Liquid)', 'Valves and General Accessories', 'Valves and General Accessories', 'Custom', 'DeepCoolAI - Valves and General Accessories - Valves and General Accessories - Custom', '5035', '509', NULL, 1, 120000, 1100, 'DATN', 0, 0, 0, 0, 0, 0, 0, 1, 'Archived', 'Rack Frame / Accessories');
